CREATE TABLE drivers (driver_id TEXT, first_name TEXT, last_name TEXT, nationality TEXT, date_of_birth TEXT);
CREATE TABLE teams (team_id TEXT, name TEXT, country TEXT);
CREATE TABLE circuits (circuit_id TEXT, name TEXT, place TEXT, country TEXT);
CREATE TABLE races (race_id INTEGER, year INTEGER, round INTEGER, race_date TEXT, grand_prix TEXT, circuit_id TEXT, laps INTEGER);
CREATE TABLE results (race_id INTEGER, driver_id TEXT, team_id TEXT, grid INTEGER, position INTEGER, points REAL, laps INTEGER, status TEXT, time_ms INTEGER);
CREATE TABLE pit_stops (race_id INTEGER, driver_id TEXT, stop INTEGER, lap INTEGER, duration_ms INTEGER);
CREATE TABLE qualifying (race_id INTEGER, driver_id TEXT, team_id TEXT, position INTEGER, q1_ms INTEGER, q2_ms INTEGER, q3_ms INTEGER, time_ms INTEGER);
CREATE TABLE driver_standings (year INTEGER, position INTEGER, driver_id TEXT, points REAL, champion INTEGER);
